  ctx.save();if(e.facing<0)ctx.scale(-1,1);ctx.translate(0,pose.drop);ctx.rotate(pose.angle);ctx.drawImage(f.image,f.x,f.y,f.w,f.h,Math.round(-w/2),Math.round(-h),Math.round(w),Math.round(h));
  if(e.miniMap==='machu'){
   ctx.strokeStyle='#39291e';ctx.lineWidth=3;const crack=Math.min(1,t/.28);ctx.beginPath();ctx.moveTo(-w*.12,-h*.8);ctx.lineTo(w*.06,-h*(.8-.18*crack));ctx.lineTo(-w*.08,-h*(.8-.4*crack));ctx.lineTo(w*.14,-h*(.8-.65*crack));ctx.stroke();ctx.strokeStyle='#efc985';ctx.lineWidth=1;ctx.stroke()
  }ctx.restore()
