   const a=i*2.399,flight=Math.min(1,t/.7),x=Math.cos(a)*(20+i*3)*flight,y=-45-Math.sin(flight*Math.PI)*(35+i%4*12)+flight*65,spin=a+t*(i%2?4:-4);
